import java.util.*;

class LFUCache {
  private final int capacity;
  private int minFreq;
  private final Map<Integer, Integer> values = new HashMap<>(), freq = new HashMap<>();
  private final Map<Integer, LinkedHashSet<Integer>> byFreq = new HashMap<>(); // insertion order = recency

  public LFUCache(int capacity) {
    this.capacity = capacity;
  }

  public int get(int key) {
    if (!values.containsKey(key)) return -1;
    touch(key);
    return values.get(key);
  }

  public void put(int key, int value) {
    if (capacity <= 0) return;
    if (values.containsKey(key)) {
      values.put(key, value);
      touch(key);
      return;
    }
    if (values.size() == capacity) {
      Iterator<Integer> it = byFreq.get(minFreq).iterator();
      int evict = it.next();
      it.remove();
      values.remove(evict);
      freq.remove(evict);
    }
    values.put(key, value);
    freq.put(key, 1);
    byFreq.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
    minFreq = 1;
  }

  private void touch(int key) {
    int f = freq.get(key);
    freq.put(key, f + 1);
    LinkedHashSet<Integer> set = byFreq.get(f);
    set.remove(key);
    if (f == minFreq && set.isEmpty()) minFreq++;
    byFreq.computeIfAbsent(f + 1, k -> new LinkedHashSet<>()).add(key);
  }
}
